//! Pre-encoded H.264/HEVC clips replayed by the fake VENC instead of synthetic packets.
//!
//! Clips are Annex-B streams that start with an IDR, have no B-frames and repeat the
//! parameter sets before every IDR, so they can be looped frame by frame. The embedded
//! clips are generated by `clips/generate.sh`. `ROCKIT_STUB_H264_CLIP` and
//! `ROCKIT_STUB_HEVC_CLIP` replace them with a file.

use std::sync::OnceLock;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum Codec {
    H264,
    Hevc,
}

/// One access unit with its start codes.
pub(crate) struct Frame {
    pub data: Vec<u8>,
    pub idr: bool,
}

pub(crate) struct Clip {
    pub name: String,
    /// `None` for clips loaded from a file
    pub size: Option<(u32, u32)>,
    pub frames: Vec<Frame>,
}

#[cfg(feature = "clips")]
const EMBEDDED: &[(Codec, u32, u32, &str, &[u8])] = &[
    (Codec::H264, 1280, 720, "720p.h264", include_bytes!("../clips/720p.h264")),
    (Codec::H264, 1920, 1080, "1080p.h264", include_bytes!("../clips/1080p.h264")),
    (Codec::Hevc, 1280, 720, "720p.hevc", include_bytes!("../clips/720p.hevc")),
    (Codec::Hevc, 1920, 1080, "1080p.hevc", include_bytes!("../clips/1080p.hevc")),
];

#[cfg(not(feature = "clips"))]
const EMBEDDED: &[(Codec, u32, u32, &str, &[u8])] = &[];

fn embedded() -> &'static [Clip] {
    static CLIPS: OnceLock<Vec<Clip>> = OnceLock::new();
    CLIPS.get_or_init(|| {
        EMBEDDED
            .iter()
            .map(|&(codec, width, height, name, data)| {
                let frames = split_frames(codec, data).expect("invalid embedded clip");
                Clip { name: name.to_string(), size: Some((width, height)), frames }
            })
            .collect()
    })
}

fn from_env(codec: Codec) -> Option<&'static Clip> {
    static H264: OnceLock<Option<Clip>> = OnceLock::new();
    static HEVC: OnceLock<Option<Clip>> = OnceLock::new();
    let (cell, var) = match codec {
        Codec::H264 => (&H264, "ROCKIT_STUB_H264_CLIP"),
        Codec::Hevc => (&HEVC, "ROCKIT_STUB_HEVC_CLIP"),
    };
    cell.get_or_init(|| {
        let path = std::env::var(var).ok()?;
        let result = std::fs::read(&path)
            .map_err(|e| e.to_string())
            .and_then(|data| split_frames(codec, &data));
        match result {
            Ok(frames) => Some(Clip { name: path, size: None, frames }),
            Err(e) => {
                eprintln!("rockit-stub: ignoring {var}={path}: {e}");
                None
            }
        }
    })
    .as_ref()
}

/// The clip for a channel: the one from the environment, else the embedded clip of the
/// same size, else the embedded clip closest in size.
pub(crate) fn select(codec: Codec, width: u32, height: u32) -> Option<&'static Clip> {
    if let Some(clip) = from_env(codec) {
        return Some(clip);
    }
    let candidates = embedded().iter().zip(EMBEDDED).filter(|(_, e)| e.0 == codec);
    let area = |(w, h): (u32, u32)| w as i64 * h as i64;
    let (clip, _) = candidates.min_by_key(|(clip, _)| {
        let size = clip.size.unwrap();
        (size != (width, height), (area(size) - area((width, height))).abs())
    })?;
    if clip.size != Some((width, height)) {
        eprintln!(
            "rockit-stub: no {codec:?} clip for {width}x{height}, using {}",
            clip.name
        );
    }
    Some(clip)
}

/// Splits an Annex-B stream into NAL units (without start codes).
fn nal_units(data: &[u8]) -> Vec<&[u8]> {
    let mut starts = Vec::new();
    let mut i = 0;
    while i + 3 <= data.len() {
        if data[i..i + 3] == [0, 0, 1] {
            starts.push(i + 3);
            i += 3;
        } else {
            i += 1;
        }
    }
    starts
        .iter()
        .enumerate()
        .map(|(n, &start)| {
            let end = starts.get(n + 1).map_or(data.len(), |&next| next - 3);
            // Trailing zeros belong to the next (4-byte) start code
            let mut nal = &data[start..end];
            while let [rest @ .., 0] = nal {
                nal = rest;
            }
            nal
        })
        .filter(|nal| !nal.is_empty())
        .collect()
}

struct NalInfo {
    vcl: bool,
    /// VCL: first slice of a picture. Non-VCL: may only precede the first slice.
    starts_picture: bool,
    idr: bool,
}

fn nal_info(codec: Codec, nal: &[u8]) -> Option<NalInfo> {
    match codec {
        Codec::H264 => {
            let nal_type = nal.first()? & 0x1f;
            let vcl = (1..=5).contains(&nal_type);
            Some(NalInfo {
                vcl,
                // first_mb_in_slice == 0 is coded as a single 1 bit
                starts_picture: if vcl {
                    nal.get(1)? & 0x80 != 0
                } else {
                    matches!(nal_type, 6..=9 | 14..=18)
                },
                idr: nal_type == 5,
            })
        }
        Codec::Hevc => {
            let nal_type = (nal.first()? >> 1) & 0x3f;
            let vcl = nal_type < 32;
            Some(NalInfo {
                vcl,
                // first_slice_segment_in_pic_flag
                starts_picture: if vcl {
                    nal.get(2)? & 0x80 != 0
                } else {
                    matches!(nal_type, 32..=35 | 39 | 41..=44 | 48..=55)
                },
                idr: (16..=21).contains(&nal_type),
            })
        }
    }
}

/// Groups NAL units into access units. The first one must be an IDR.
pub(crate) fn split_frames(codec: Codec, data: &[u8]) -> Result<Vec<Frame>, String> {
    let mut frames = Vec::new();
    let mut current: Option<Frame> = None;
    let mut has_vcl = false;
    for nal in nal_units(data) {
        let info = nal_info(codec, nal).ok_or("truncated NAL unit")?;
        if info.starts_picture && has_vcl {
            frames.extend(current.take());
            has_vcl = false;
        }
        let frame = current.get_or_insert_with(|| Frame { data: Vec::new(), idr: false });
        frame.data.extend_from_slice(&[0, 0, 0, 1]);
        frame.data.extend_from_slice(nal);
        frame.idr |= info.idr;
        has_vcl |= info.vcl;
    }
    if has_vcl {
        frames.extend(current);
    }
    match frames.first() {
        None => Err("no pictures found".to_string()),
        Some(frame) if !frame.idr => Err("the first picture is not an IDR".to_string()),
        Some(_) => Ok(frames),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn types(codec: Codec, frame: &Frame) -> Vec<u8> {
        nal_units(&frame.data)
            .iter()
            .map(|nal| match codec {
                Codec::H264 => nal[0] & 0x1f,
                Codec::Hevc => (nal[0] >> 1) & 0x3f,
            })
            .collect()
    }

    #[test]
    fn splits_h264_access_units() {
        // SPS, PPS, IDR in two slices, P, AUD + P with a 3-byte start code
        let data = [
            &[0, 0, 0, 1, 0x67, 0xaa][..],
            &[0, 0, 0, 1, 0x68, 0xbb],
            &[0, 0, 0, 1, 0x65, 0x88, 0x01],
            &[0, 0, 0, 1, 0x65, 0x40, 0x02],
            &[0, 0, 0, 1, 0x41, 0x9a, 0x03],
            &[0, 0, 1, 0x09, 0xf0],
            &[0, 0, 1, 0x41, 0x9a, 0x04],
        ]
        .concat();
        let frames = split_frames(Codec::H264, &data).unwrap();
        let summary: Vec<_> = frames.iter().map(|f| (types(Codec::H264, f), f.idr)).collect();
        assert_eq!(
            summary,
            [(vec![7, 8, 5, 5], true), (vec![1], false), (vec![9, 1], false)]
        );
        assert_eq!(frames[1].data, [0, 0, 0, 1, 0x41, 0x9a, 0x03]);
    }

    #[test]
    fn splits_hevc_access_units() {
        let data = [
            &[0, 0, 0, 1, 0x40, 0x01, 0x0c][..],
            &[0, 0, 0, 1, 0x42, 0x01, 0x01],
            &[0, 0, 0, 1, 0x44, 0x01, 0xc1],
            &[0, 0, 0, 1, 0x28, 0x01, 0xaf],
            &[0, 0, 0, 1, 0x02, 0x01, 0xd0],
            // Suffix SEI stays with its picture
            &[0, 0, 0, 1, 0x50, 0x01, 0x01],
            &[0, 0, 0, 1, 0x02, 0x01, 0xd1],
        ]
        .concat();
        let frames = split_frames(Codec::Hevc, &data).unwrap();
        let summary: Vec<_> = frames.iter().map(|f| (types(Codec::Hevc, f), f.idr)).collect();
        assert_eq!(
            summary,
            [(vec![32, 33, 34, 20], true), (vec![1, 40], false), (vec![1], false)]
        );
    }

    #[test]
    fn rejects_clips_without_leading_idr() {
        let data = [0, 0, 0, 1, 0x41, 0x9a, 0x03];
        assert!(split_frames(Codec::H264, &data).is_err());
        assert!(split_frames(Codec::H264, &[]).is_err());
    }

    #[cfg(feature = "clips")]
    #[test]
    fn embedded_clips_loop() {
        for (clip, &(codec, ..)) in embedded().iter().zip(EMBEDDED) {
            assert_eq!(clip.frames.len(), 60, "{}", clip.name);
            let idrs: Vec<_> =
                clip.frames.iter().enumerate().filter(|(_, f)| f.idr).map(|(i, _)| i).collect();
            assert_eq!(idrs, [0, 30], "{}", clip.name);
            let param_sets = match codec {
                Codec::H264 => vec![7, 8],
                Codec::Hevc => vec![32, 33, 34],
            };
            for i in idrs {
                let types = types(codec, &clip.frames[i]);
                assert_eq!(types[..param_sets.len()], param_sets, "{} frame {i}", clip.name);
            }
        }
    }

    #[cfg(feature = "clips")]
    #[test]
    fn selects_closest_clip() {
        assert_eq!(select(Codec::Hevc, 1920, 1080).unwrap().name, "1080p.hevc");
        assert_eq!(select(Codec::H264, 1280, 720).unwrap().name, "720p.h264");
        assert_eq!(select(Codec::H264, 640, 480).unwrap().name, "720p.h264");
        assert_eq!(select(Codec::H264, 1920, 1200).unwrap().name, "1080p.h264");
    }
}
